#!/usr/bin/env bash
#
# Analyse trajectory metrics and generate summary figures.
#
# Usage:
#   ./analyse_trajectory_metrics.sh CONFIG_FILE
#
# The Python interpreter is read from python.conf, generated by
# setup_python.sh. Analysis parameters are read from CONFIG_FILE.
#

set -Eeuo pipefail

cd "$(dirname "$0")"

die() {
    printf 'Error: %s\n' "$*" >&2
    exit 1
}

usage() {
    cat <<EOF
Usage:
  $(basename "$0") CONFIG_FILE

CONFIG_FILE is a trusted Bash configuration file containing the input/output
paths and analysis parameters.
EOF
}

if (( $# != 1 )); then
    usage >&2
    exit 1
fi

case "$1" in
    -h|--help)
        usage
        exit 0
        ;;
esac

PYTHON_CONFIG="python.conf"
ANALYSIS_CONFIG="$1"
PYTHON_SCRIPT="analyse_trajectory_metrics.py"

[[ -f "$PYTHON_CONFIG" ]] \
    || die "Python configuration file not found: $PYTHON_CONFIG"

[[ -f "$ANALYSIS_CONFIG" ]] \
    || die "Analysis configuration file not found: $ANALYSIS_CONFIG"

[[ -f "$PYTHON_SCRIPT" ]] \
    || die "Python script not found: $PYTHON_SCRIPT"

# shellcheck disable=SC1090
source "$PYTHON_CONFIG"

# shellcheck disable=SC1090
source "$ANALYSIS_CONFIG"

: "${PYTHON:?PYTHON is not defined in $PYTHON_CONFIG}"
: "${METRICS_DIR:?METRICS_DIR is not defined in $ANALYSIS_CONFIG}"

[[ -x "$PYTHON" ]] \
    || die "Python interpreter is not executable: $PYTHON"

[[ -d "$METRICS_DIR" ]] \
    || die "Metrics directory not found: $METRICS_DIR"

OUTPUT_DIR="${OUTPUT_DIR:-$METRICS_DIR/grouped_analysis}"
DPI="${DPI:-300}"
STATE_SPEED_THRESHOLD="${STATE_SPEED_THRESHOLD:-}"
BINS="${BINS:-50}"
COUPLING_BINS="${COUPLING_BINS:-20}"
SMOOTH_FRAC="${SMOOTH_FRAC:-0.20}"

mkdir -p "$OUTPUT_DIR"

args=(
    "$METRICS_DIR"
    --outdir "$OUTPUT_DIR"
    --dpi "$DPI"
    --bins "$BINS"
    --coupling-bins "$COUPLING_BINS"
    --smooth-frac "$SMOOTH_FRAC"
)

if [[ -n "$STATE_SPEED_THRESHOLD" ]]; then
    args+=(
        --state-speed-threshold "$STATE_SPEED_THRESHOLD"
    )
fi

echo "Analysing trajectory metrics..."
echo "  Metrics: $METRICS_DIR"
echo "  Output:  $OUTPUT_DIR"
echo "  Python:  $PYTHON"

"$PYTHON" "$PYTHON_SCRIPT" "${args[@]}"

echo "Trajectory analysis completed."
